			"python3 scripts/run_workflow.py \\\r",
			"  --workflow flux_dev.json \\\r",
			"  --args '{\"prompt\": \"...\"}' \\\r",
			"  --ws\r",
			"\r",
			"# img2img / inpaint: pass --input-image to upload + reference automatically\r",
			"python3 scripts/run_workflow.py \\\r",
