			"{\r",
			"  \"results\": {\r",
			"    \"mmlu\": {\r",
			"      \"acc\": 0.459,\r",
			"      \"acc_stderr\": 0.004\r",
			"    },\r",
			"    \"gsm8k\": {\r",
			"      \"exact_match\": 0.142,\r",
			"      \"exact_match_stderr\": 0.006\r",
