			"\r",
			"### With PyTorch\r",
			"\r",
			"```python\r",
			"import torch\r",
			"import wandb\r",
			"\r",
			"# Initialize\r",
			"wandb.init(project=\"pytorch-demo\", config={\r",
			"    \"lr\": 0.001,\r",
			"    \"epochs\": 10\r",
			"})\r",
			"\r",
			"# Access config\r",
			"config = wandb.config\r",
			"\r",
			"# Training loop\r",
			"for epoch in range(config.epochs):\r",
			"    for batch_idx, (data, target) in enumerate(train_loader):\r",
			"        # Forward pass\r",
			"        output = model(data)\r",
			"        loss = criterion(output, target)\r",
			"\r",
			"        # Backward pass\r",
			"        optimizer.zero_grad()\r",
			"        loss.backward()\r",
			"        optimizer.step()\r",
			"\r",
			"        # Log every 100 batches\r",
			"        if batch_idx % 100 == 0:\r",
			"            wandb.log({\r",
			"                \"loss\": loss.item(),\r",
			"                \"epoch\": epoch,\r",
			"                \"batch\": batch_idx\r",
